document.querySelectorAll('[data-lab="L16-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const angle=root.querySelector('[data-angle]'),stretch=root.querySelector('[data-stretch]'),view=root.querySelector('[data-view]'),en=root.dataset.lang==='en',ns='http://www.w3.org/2000/svg',raw=[[-2,0],[-1,.8],[-1,-.8],[1,.8],[1,-.8],[2,0]],edges=[[0,1],[1,2],[2,0],[3,4],[4,5],[5,3],[1,3]];function element(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}function draw(){const t=+angle.value*Math.PI/180,l=+stretch.value,reference=raw.map(([x,y])=>[x*Math.cos(t)-y*Math.sin(t),x*Math.sin(t)+y*Math.cos(t)]),current=reference.map(([x,y])=>[l*x,y/Math.sqrt(l)]),map=([x,y])=>[450+78*x,255-78*y];root.querySelector('[data-angle-value]').textContent=angle.value;root.querySelector('[data-stretch-value]').textContent=l.toFixed(2);const rg=root.querySelector('[data-reference]'),eg=root.querySelector('[data-edges]'),pg=root.querySelector('[data-points]');rg.replaceChildren();eg.replaceChildren();pg.replaceChildren();let energy=0;for(const[a,b]of edges){const r0=Math.hypot(reference[a][0]-reference[b][0],reference[a][1]-reference[b][1]),r=Math.hypot(current[a][0]-current[b][0],current[a][1]-current[b][1]);energy+=.5*(r-r0)**2;for(const[points,group]of[[reference,rg],[current,eg]]){const[x1,y1]=map(points[a]),[x2,y2]=map(points[b]);element('line',{x1,y1,x2,y2},group);}}current.forEach((p,i)=>{const[x,y]=map(p);element('circle',{cx:x,cy:y,r:10,fill:'#c16b3d'},pg);const label=element('text',{x:x+14,y:y-14,'font-size':22,fill:'#163840'},pg);label.textContent=i+1;});rg.style.display=view.value==='both'?'':'none';root.querySelector('[data-answer]').textContent=(en?'Spring energy U = ':'弹簧能U = ')+energy.toFixed(6)+' ε; '+(en?'largest fraction = 1; cycles = 2. ':'最大分量占比 = 1；独立循环数 = 2。')+(en?'Prescribed geometry with k=1 ε/σ²; nodes follow the affine map.':'刚度k=1ε/σ²，节点按指定仿射映射移动。');}angle.addEventListener('input',draw);stretch.addEventListener('input',draw);view.addEventListener('change',draw);root.querySelector('[data-reset]').addEventListener('click',()=>{angle.value='0';stretch.value='1.2';view.value='both';draw();});draw();});